using DigitalEvidenceSystem.Web.Data; using DigitalEvidenceSystem.Web.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace DigitalEvidenceSystem.Web.Pages.Cases; [Authorize] public sealed class IndexModel(EvidenceDbContext db):PageModel { public List<CaseFile> Items {get;set;}=[]; public string? Query {get;set;} public string? Status {get;set;} public string[] Statuses=>["Open","In Progress","Pending Review","Closed"]; public async Task OnGetAsync(string? q,string? status){Query=q;Status=status;var cases=db.Cases.AsQueryable();if(!string.IsNullOrWhiteSpace(q))cases=cases.Where(c=>c.CaseNumber.Contains(q)||c.Title.Contains(q));if(!string.IsNullOrWhiteSpace(status))cases=cases.Where(c=>c.Status==status);Items=await cases.OrderByDescending(c=>c.OpenedOn).ToListAsync();}}
